cat > src/greet.js <<'EOF'
// Greets a person by name.
//   greet("Ada") // => "Hello, Ada!"
//   greet("")    // throws Error("name is required")
export function greet(name) {
  if (name.trim() === "") {
    throw new Error("name is required");
  }
  return `Hello, ${name}!`;
}
EOF
cat > src/index.js <<'EOF'
// Entry point for the greeting tool. Functions are added by the greeting-cli PRD.
export { greet } from "./greet.js";
EOF
cat > test/greet.test.js <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { greet } from "../src/index.js";

test("greets by name (AC-GREET-01)", () => {
  assert.equal(greet("Ada"), "Hello, Ada!");
});

test("refuses an empty or blank name (AC-GREET-02)", () => {
  for (const name of ["", "   "]) {
    assert.throws(() => greet(name), { name: "Error", message: "name is required" });
  }
});
EOF
